      <p className="text-gray-500 text-sm mb-3">気になる点：フレームが大きすぎると顔とのバランスが崩れやすいため、サイズ表示を確認してから選びたい</p>
      {MARUGAO_MEGANE_PRODUCT && <MoshimoProductCard product={MARUGAO_MEGANE_PRODUCT} />}

